/* ---------- small helpers ---------- */

static int32_t px(const h2_g99_app_t* app, float units) {
  return (int32_t)lroundf(units * app->layout.k);
}

static lv_opa_t opa_of(float value) {
  return (lv_opa_t)lroundf(h2_g99_clamp01(value) * 255.0f);
}

/* LVGL redraws an object on every style set, an unchanged value included,
 * and Main places every element on each loop: set opacity only on change. */
static void set_opa(lv_obj_t* obj, lv_opa_t opa) {
  if (obj != NULL && lv_obj_get_style_opa(obj, LV_PART_MAIN) != opa)
    lv_obj_set_style_opa(obj, opa, LV_PART_MAIN);
}

static void set_image_opa(lv_obj_t* obj, lv_opa_t opa) {
  if (obj != NULL && lv_obj_get_style_image_opa(obj, LV_PART_MAIN) != opa)
    lv_obj_set_style_image_opa(obj, opa, LV_PART_MAIN);
}

static lv_obj_t* plain(lv_obj_t* parent) {
  lv_obj_t* obj = lv_obj_create(parent);
  if (obj == NULL) return NULL;
  lv_obj_remove_style_all(obj);
  lv_obj_set_scrollable(obj, false);
  lv_obj_set_clickable(obj, false);
  return obj;
}

static lv_obj_t* full(lv_obj_t* parent, const h2_g99_app_t* app) {
  lv_obj_t* obj = plain(parent);
  if (obj != NULL) {
    lv_obj_set_pos(obj, 0, 0);
    lv_obj_set_size(obj, app->layout.width, app->layout.height);
  }
  return obj;
}

static lv_obj_t* rect(lv_obj_t* parent, int32_t x, int32_t y, int32_t w,
                      int32_t h, uint32_t rgb, lv_opa_t opa, int32_t radius) {
  lv_obj_t* obj = plain(parent);
  if (obj == NULL) return NULL;
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_size(obj, w, h);
  lv_obj_set_style_bg_color(obj, lv_color_hex(rgb), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(obj, opa, LV_PART_MAIN);
  lv_obj_set_style_radius(obj, radius, LV_PART_MAIN);
  return obj;
}

static lv_obj_t* text(lv_obj_t* parent, const lv_font_t* font, uint32_t rgb,
                      int32_t x, int32_t y, const char* value) {
  lv_obj_t* label = lv_label_create(parent);
  if (label == NULL) return NULL;
  lv_obj_set_style_text_font(label, font, LV_PART_MAIN);
  lv_obj_set_style_text_color(label, lv_color_hex(rgb), LV_PART_MAIN);
  lv_label_set_text(label, value);
  lv_obj_set_pos(label, x, y);
  return label;
}

static lv_obj_t* text_clipped(lv_obj_t* parent, const lv_font_t* font,
                              uint32_t rgb, int32_t x, int32_t y, int32_t w,
                              const char* value) {
  lv_obj_t* label = text(parent, font, rgb, x, y, value);
  if (label != NULL) {
    lv_label_set_long_mode(label, LV_LABEL_LONG_MODE_DOTS);
    lv_obj_set_width(label, w);
  }
  return label;
}

static int32_t line_h(const lv_font_t* font) {
  return lv_font_get_line_height(font);
}

static int32_t text_w(const lv_font_t* font, const char* value) {
  lv_point_t size = {0, 0};
  lv_text_get_size(&size, value, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
  return size.x;
}

static lv_obj_t* image(lv_obj_t* parent, const h2_g99_image_t* img, int32_t x,
                       int32_t y) {
  lv_obj_t* obj = lv_image_create(parent);
  if (obj == NULL) return NULL;
  lv_image_set_src(obj, &img->dsc);
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_clickable(obj, false);
  return obj;
}

static bool image_alloc(h2_g99_app_t* app, h2_g99_image_t* img, int32_t w,
                        int32_t h, lv_color_format_t cf, uint32_t bpp) {
  const size_t size = (size_t)w * (size_t)h * bpp;
  img->pixels = h2_pal_mem_alloc(app->runtime->mem, size);
  if (img->pixels == NULL) return false;
  memset(img->pixels, 0, size);
  memset(&img->dsc, 0, sizeof(img->dsc));
  img->dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
  img->dsc.header.cf = cf;
  img->dsc.header.w = (uint32_t)w;
  img->dsc.header.h = (uint32_t)h;
  img->dsc.header.stride = (uint32_t)w * bpp;
  img->dsc.data_size = (uint32_t)size;
  img->dsc.data = img->pixels;
  return true;
}

static bool argb_alloc(h2_g99_app_t* app, h2_g99_image_t* img, int32_t w,
                       int32_t h) {
  return image_alloc(app, img, w, h, LV_COLOR_FORMAT_ARGB8888, 4u);
}

/* Monochrome wheel art needs only its coverage. Transforming an A8 mask
 * interpolates one channel; the image style supplies the constant colour. */
static void image_to_alpha(h2_g99_app_t* app, h2_g99_image_t* img) {
  const size_t size = (size_t)img->dsc.header.w * img->dsc.header.h;
  for (size_t i = 0u; i < size; ++i) img->pixels[i] = img->pixels[i * 4u + 3u];
  uint8_t* pixels = h2_pal_mem_realloc(app->runtime->mem, img->pixels, size);
  if (pixels != NULL) img->pixels = pixels;
  img->dsc.header.cf = LV_COLOR_FORMAT_A8;
  img->dsc.header.stride = img->dsc.header.w;
  img->dsc.data_size = (uint32_t)size;
  img->dsc.data = img->pixels;
}

static void image_free(h2_g99_app_t* app, h2_g99_image_t* img) {
  if (img->pixels != NULL) h2_pal_mem_free(app->runtime->mem, img->pixels);
  memset(img, 0, sizeof(*img));
}

static bool ready_for_touch(const h2_g99_app_t* app) {
  return !app->press_ignored && app->nav.screen_on &&
         h2_g99_nav_input_ready(&app->nav);
}

static h2_g99_wheel_kind_t wheel_kind(h2_g99_route_t route) {
  return route == H2_G99_ROUTE_LIBRARY ? H2_G99_WHEEL_THUMBS
                                       : H2_G99_WHEEL_ICONS;
}

/* A finger turns the wheel of a page outside editing that has two items or
 * more. */
static bool wheel_turnable(const h2_g99_app_t* app) {
  const h2_g99_nav_t* nav = &app->nav;
  if (nav->editing || nav->text_entry) return false;
  if (nav->route != H2_G99_ROUTE_MAIN && nav->route != H2_G99_ROUTE_LIBRARY &&
      nav->route != H2_G99_ROUTE_SETTINGS)
    return false;
  return h2_g99_nav_route_count(nav, nav->route) >= 2u;
}

/* Finger travel in pixels per item at the selection, where the wheel moves
 * along its arc at radius times its angular step. */
static float wheel_pitch(const h2_g99_app_t* app) {
  return h2_g99_wheel_step(&app->layout, wheel_kind(app->nav.route)) *
         (float)app->layout.radius;
}

/* ---------- display flush ---------- */

static void display_flush(lv_display_t* display, const lv_area_t* area,
                          uint8_t* pixels) {
  h2_g99_app_t* app = lv_display_get_user_data(display);
  if (app != NULL && !app->suppress_flush && area != NULL && pixels != NULL) {
    const h2_display_rect_t rect_area = {
        area->x1, area->y1, area->x2 - area->x1 + 1, area->y2 - area->y1 + 1};
    const uint64_t draw_start = h2_g99_now_us(app);
    int rc = h2_pal_display_draw_bitmap(
        app->runtime->display, &rect_area, pixels,
        lv_draw_buf_width_to_stride((uint32_t)rect_area.width,
                                    LV_COLOR_FORMAT_RGB565),
        H2_DISPLAY_PIXEL_RGB565);
    const uint64_t draw_end = h2_g99_now_us(app);
    app->frame_draw_us += draw_end - draw_start;
    app->frame_pixels += (uint64_t)rect_area.width * (uint64_t)rect_area.height;
    if (rc == H2_PAL_OK && lv_display_flush_is_last(display)) {
      rc = h2_pal_display_present(app->runtime->display);
      app->frame_present_us += h2_g99_now_us(app) - draw_end;
      app->frame_presented = true;
    }
    if (rc != H2_PAL_OK && app->flush_result == H2_PAL_OK)
      app->flush_result = (h2_pal_result_t)rc;
  }
  lv_display_flush_ready(display);
}

/* ---------- touch ---------- */

static void request_action(h2_g99_app_t* app, h2_g99_action_t action) {
  app->touch_request.action = (int)action;
}

static void on_indev_press(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  /* A finger on the turning wheel stops it on its target at once, so quick
   * consecutive drags all count. */
  if (app->nav.screen_on)
    (void)h2_g99_nav_finish_rotate(&app->nav, app->now_ms);
  /* A press that starts while input is gated is dropped as a whole. */
  app->press_ignored = !app->nav.screen_on ||
                       !h2_g99_nav_input_ready(&app->nav) ||
                       app->nav.route == H2_G99_ROUTE_APP;
  if (!app->nav.screen_on) request_action(app, H2_G99_ACTION_OK);
}

/* Counts one touch read of the current press and its gap to the last. */
static void note_touch_read(h2_g99_app_t* app) {
  const uint64_t now = h2_g99_now_us(app) / 1000u;
  const uint64_t gap = now - app->press_last_ms;
  if (gap > app->press_gap_ms)
    app->press_gap_ms = gap > UINT32_MAX ? UINT32_MAX : (uint32_t)gap;
  app->press_last_ms = now;
  ++app->press_samples;
}

/* Acts on a released press; returns what it did, for the touch log. */
static const char* release_gesture(h2_g99_app_t* app, lv_point_t point) {
  if (!ready_for_touch(app)) return "dropped";
  const h2_g99_layout_t* l = &app->layout;
  const int32_t dy = point.y - app->press_start.y;
  if (dy > px(app, 18.0f) || dy < -px(app, 18.0f)) {
    /* Dragging the wheel up brings the next item to the centre. */
    request_action(app, dy < 0 ? H2_G99_ACTION_DOWN : H2_G99_ACTION_UP);
    return dy < 0 ? "drag down" : "drag up";
  }
  if (app->nav.editing) return "tap ignored";
  if (point.x < l->panel_x) {
    const h2_g99_wheel_kind_t kind = app->nav.route == H2_G99_ROUTE_LIBRARY
                                         ? H2_G99_WHEEL_THUMBS
                                         : H2_G99_WHEEL_ICONS;
    const float step = h2_g99_wheel_step(l, kind);
    float ratio = (float)(point.y - l->cy) / (float)l->radius;
    ratio = ratio > 1.0f ? 1.0f : (ratio < -1.0f ? -1.0f : ratio);
    const int d = step > 0.0f ? (int)lroundf(asinf(ratio) / step) : 0;
    request_action(app, d == 0
                            ? H2_G99_ACTION_OK
                            : (d > 0 ? H2_G99_ACTION_DOWN : H2_G99_ACTION_UP));
    return d == 0 ? "tap ok" : (d > 0 ? "tap down" : "tap up");
  }
  if (app->nav.route != H2_G99_ROUTE_MAIN) return "tap ignored";
  request_action(app, H2_G99_ACTION_OK);
  return "tap ok";
}

/* Turns a turnable wheel with the finger once it moved past the slop. */
static void follow_drag(h2_g99_app_t* app, lv_point_t point) {
  const int32_t dy = point.y - app->press_start.y;
  if (!app->dragging) {
    const int32_t slop = px(app, H2_G99_DRAG_SLOP);
    if ((dy < slop && dy > -slop) ||
        app->press_start.x >= app->layout.panel_x || !ready_for_touch(app) ||
        !wheel_turnable(app))
      return;
    app->dragging = true;
  }
  /* Dragging up brings the next items to the centre. */
  const float pitch = wheel_pitch(app);
  const float target = pitch > 0.0f ? -(float)dy / pitch : 0.0f;
  const uint64_t elapsed =
      app->now_ms >= app->drag_last_ms ? app->now_ms - app->drag_last_ms : 0u;
  app->drag_last_ms = app->now_ms;
  app->drag_offset = h2_g99_wheel_follow(
      app->drag_offset, target, (uint32_t)(elapsed > 50u ? 50u : elapsed));
  app->nav.last_input_ms = app->now_ms;
}

/* A release always starts a finite, damped transition to a magnetic
 * detent, including a small drag that settles back on the current item. */
static void end_drag(h2_g99_app_t* app, char* outcome, size_t size) {
  const float offset = app->drag_offset;
  const int steps = h2_g99_wheel_snap(offset);
  app->dragging = false;
  app->drag_offset = 0.0f;
  const h2_g99_nav_result_t result =
      h2_g99_nav_rotate_from(&app->nav, steps, offset, app->now_ms);
  (void)snprintf(
      outcome, size, "drag offset=%d%% steps=%d%s",
      (int)lroundf(offset * 100.0f), steps,
      result == H2_G99_NAV_CHANGED || offset == 0.0f ? "" : " dropped");
}

static void on_catcher(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  lv_indev_t* indev = lv_indev_active();
  lv_point_t point = {0, 0};
  if (indev != NULL) lv_indev_get_point(indev, &point);
  if (code == LV_EVENT_PRESSED) {
    app->press_active = true;
    app->press_start = point;
    app->dragging = false;
    app->drag_offset = 0.0f;
    app->drag_last_ms = app->now_ms;
    app->press_samples = 1u;
    app->press_gap_ms = 0u;
    app->press_last_ms = h2_g99_now_us(app) / 1000u;
    app->press_touch = app->touch_filter.stats;
    return;
  }
  if (code == LV_EVENT_PRESSING) {
    if (!app->press_active) return;
    note_touch_read(app);
    follow_drag(app, point);
    return;
  }
  if (code == LV_EVENT_PRESS_LOST) {
    char lost[48];
    if (app->press_active && app->dragging) end_drag(app, lost, sizeof(lost));
    app->press_active = false;
    return;
  }
  if (code != LV_EVENT_RELEASED || !app->press_active) return;
  app->press_active = false;
  note_touch_read(app);
  char outcome[48];
  if (app->dragging) {
    follow_drag(app, point);
    end_drag(app, outcome, sizeof(outcome));
  } else {
    (void)snprintf(outcome, sizeof(outcome), "%s", release_gesture(app, point));
  }
  /* rejoined: source releases the filter merged back into this press;
   * failed: source reads that failed during it. */
  const h2_g99_touch_stats_t* t = &app->touch_filter.stats;
  h2_g99_log(app, "touch dy=%d reads=%u gap=%ums rejoined=%u failed=%u %s",
             (int)(point.y - app->press_start.y), (unsigned)app->press_samples,
             (unsigned)app->press_gap_ms,
             (unsigned)(t->rejoined - app->press_touch.rejoined),
             (unsigned)(t->failed - app->press_touch.failed), outcome);
}

static void on_ok_button(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  if (ready_for_touch(app)) request_action(app, H2_G99_ACTION_OK);
}

static void on_row(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  lv_obj_t* target = lv_event_get_current_target_obj(event);
  if (target != NULL && ready_for_touch(app))
    app->touch_request.row = (int)(intptr_t)lv_obj_get_user_data(target);
}

static void on_slider(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  lv_obj_t* target = lv_event_get_current_target_obj(event);
  lv_indev_t* indev = lv_indev_active();
  if (target == NULL || indev == NULL || !ready_for_touch(app)) return;
  lv_point_t point = {0, 0};
  lv_indev_get_point(indev, &point);
  lv_area_t area;
  lv_obj_get_coords(target, &area);
  const int32_t width = lv_area_get_width(&area);
  if (width <= 0) return;
  int32_t value = (point.x - area.x1) * 100 / width;
  value = (value + 5) / 10 * 10;
  app->touch_request.value = value < 0 ? 0 : (value > 100 ? 100 : value);
}

static void on_keyboard(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  if (code == LV_EVENT_READY) app->touch_request.text = H2_G99_TEXT_SUBMIT;
  if (code == LV_EVENT_CANCEL) app->touch_request.text = H2_G99_TEXT_CANCEL;
}

/* ---------- status bar ---------- */

static void add_status(h2_g99_app_t* app, lv_obj_t* parent, int32_t right,
                       int32_t top) {
  const lv_font_t* font = app->font_small;
  char clock[8] = "--:--";
  uint64_t wall_ms = 0u;
  if (h2_pal_time_get_wall_ms(app->runtime->time, &wall_ms) == H2_PAL_OK &&
      wall_ms > 1000000000000ull) {
    const uint64_t minutes =
        wall_ms / 60000u + (uint64_t)H2_G99_UTC_OFFSET_MINUTES;
    (void)snprintf(clock, sizeof(clock), "%02u:%02u",
                   (unsigned)((minutes / 60u) % 24u),
                   (unsigned)(minutes % 60u));
  }
  const int32_t lh = line_h(font);
  int32_t x = right - text_w(font, clock);
  text(parent, font, H2_G99_COLOR_MUTED, x, top, clock);
  const int32_t cy = top + lh / 2;
  if (app->battery_valid) {
    const int32_t bw = px(app, 13.0f);
    const int32_t bh = (int32_t)lroundf((float)font->line_height * 0.45f);
    x -= bw + px(app, 6.0f);
    rect(parent, x, cy - bh / 2, bw, bh, H2_G99_COLOR_MUTED, LV_OPA_40, bh / 3);
    rect(parent, x, cy - bh / 2, bw * app->battery_percent / 100, bh,
         H2_G99_COLOR_MUTED, LV_OPA_COVER, bh / 3);
    rect(parent, x + bw + 1, cy - bh / 5, px(app, 1.4f), (bh * 2) / 5,
         H2_G99_COLOR_MUTED, LV_OPA_40, 1);
  }
  if (app->wifi_state.phase != H2_G99_WIFI_UNAVAILABLE) {
    const int32_t size = (int32_t)app->tiny_wifi.dsc.header.w;
    x -= size + px(app, 4.0f);
    lv_obj_t* icon = image(parent, &app->tiny_wifi, x, cy - size / 2 - 1);
    if (icon != NULL && !app->wifi_state.connected)
      lv_obj_set_style_image_opa(icon, LV_OPA_40, LV_PART_MAIN);
  }
}

/* ---------- info pages ---------- */

static const char* wifi_line(const h2_g99_app_t* app, char* buffer,
                             size_t capacity) {
  const h2_g99_wifi_snapshot_t* w = &app->wifi_state;
  switch (w->phase) {
    case H2_G99_WIFI_UNAVAILABLE:
      return "此设备不支持 Wi-Fi";
    case H2_G99_WIFI_SCANNING:
      return "正在扫描…";
    case H2_G99_WIFI_CONNECTING:
      return "正在连接…";
    default:
      break;
  }
  if (w->connected) {
    (void)snprintf(buffer, capacity, "已连接 %s", w->connected_ssid);
    return buffer;
  }
  if (w->last_was_connect && w->last_result != H2_PAL_OK) {
    (void)snprintf(buffer, capacity, "连接失败（%d）", (int)w->last_result);
    return buffer;
  }
  return "未连接";
}

static void main_info(h2_g99_app_t* app, lv_obj_t* info, uint8_t sel) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  add_status(app, info, l->panel_x + l->panel_w - l->panel_inset, l->panel_y);
  char line[96];
  const char* status = "即将推出";
  if (sel == H2_G99_MAIN_LIBRARY) {
    (void)snprintf(line, sizeof(line), "已安装 %u 个应用",
                   (unsigned)H2_G99_LIBRARY_COUNT);
    status = line;
  } else if (sel == H2_G99_MAIN_SETTINGS) {
    char wifi[64];
    const char* w = app->wifi_state.connected
                        ? "Wi-Fi 已连接"
                        : wifi_line(app, wifi, sizeof(wifi));
    if (app->battery_valid)
      (void)snprintf(line, sizeof(line), "%s · 电量 %u%%", w,
                     (unsigned)app->battery_percent);
    else
      (void)snprintf(line, sizeof(line), "%s", w);
    status = line;
  }
  const int32_t hero = line_h(app->font_hero);
  const int32_t body = line_h(app->font_body);
  const int32_t gap = px(app, 4.0f);
  const int32_t top = l->cy - (hero + gap + body) / 2;
  text_clipped(info, app->font_hero, H2_G99_COLOR_TEXT, x, top,
               l->panel_w - l->panel_inset, kMainNames[sel]);
  text_clipped(info, app->font_body, H2_G99_COLOR_MUTED, x, top + hero + gap,
               l->panel_w - l->panel_inset, status);
}

/* Position label on the left, status on the right, then the title. Returns
 * the first free y below the title. */
static int32_t header(h2_g99_app_t* app, lv_obj_t* info, const char* label,
                      const char* title) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  text(info, app->font_small, H2_G99_COLOR_PURPLE_HI, x, l->panel_y, label);
  add_status(app, info, l->panel_x + l->panel_w - l->panel_inset, l->panel_y);
  const int32_t ty = l->panel_y + line_h(app->font_small) + px(app, 6.0f);
  text_clipped(info, app->font_title, H2_G99_COLOR_TEXT, x, ty,
               l->panel_w - 2 * l->panel_inset, title);
  return ty + line_h(app->font_title) + px(app, 4.0f);
}

static void footer(h2_g99_app_t* app, lv_obj_t* info, const char* hint) {
  const h2_g99_layout_t* l = &app->layout;
  text(info, app->font_small, H2_G99_COLOR_DIM, l->panel_x + l->panel_inset,
       l->panel_y + l->panel_h - line_h(app->font_small), hint);
}

static int32_t footer_top(const h2_g99_app_t* app) {
  return app->layout.panel_y + app->layout.panel_h - line_h(app->font_small) -
         px(app, 4.0f);
}

static void library_info(h2_g99_app_t* app, lv_obj_t* info, uint8_t sel) {
  const h2_g99_layout_t* l = &app->layout;
  char label[32];
  (void)snprintf(label, sizeof(label), "资料库  %u / %u", (unsigned)sel + 1u,
                 (unsigned)H2_G99_LIBRARY_COUNT);
  int32_t y = header(app, info, label, kAppName);
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t cw = l->panel_w - 2 * l->panel_inset;
  text(info, app->font_small, H2_G99_COLOR_MUTED, x, y, kAppAuthor);
  y += line_h(app->font_small) + px(app, 8.0f);
  static const char* const kStats[3][2] = {
      {"来源", "内置"}, {"绘图", "几何"}, {"输入", "按键"}};
  for (int i = 0; i < 3; ++i) {
    const int32_t cx = x + i * cw / 3;
    text(info, app->font_small, H2_G99_COLOR_DIM, cx, y, kStats[i][0]);
    text(info, app->font_body, H2_G99_COLOR_TEXT, cx,
         y + line_h(app->font_small) + px(app, 2.0f), kStats[i][1]);
  }
  y += line_h(app->font_small) + line_h(app->font_body) + px(app, 10.0f);
  const int32_t button_h = px(app, 22.0f);
  const int32_t button_y = footer_top(app) - button_h - px(app, 4.0f);
  if (button_y - y > line_h(app->font_small)) {
    lv_obj_t* desc =
        text(info, app->font_small, H2_G99_COLOR_MUTED, x, y, kAppDescription);
    if (desc != NULL) {
      lv_label_set_long_mode(desc, LV_LABEL_LONG_MODE_DOTS);
      lv_obj_set_size(desc, cw,
                      (button_y - y - px(app, 6.0f)) / line_h(app->font_small) *
                          line_h(app->font_small));
    }
  }
  lv_obj_t* button = rect(info, x, button_y, cw, button_h, H2_G99_COLOR_PURPLE,
                          LV_OPA_COVER, button_h / 2);
  if (button != NULL) {
    lv_obj_set_clickable(button, true);
    lv_obj_add_event_cb(button, on_ok_button, LV_EVENT_CLICKED, app);
    lv_obj_t* caption =
        text(button, app->font_body, 0xFFFFFFu, 0, 0, "开始游戏");
    if (caption != NULL) lv_obj_center(caption);
  }
  footer(app, info, "OK 开始 · AI 返回");
}

static lv_obj_t* add_row(h2_g99_app_t* app, lv_obj_t* info, int32_t y,
                         int index, bool focused) {
  const h2_g99_layout_t* l = &app->layout;
  lv_obj_t* row = plain(info);
  if (row == NULL) return NULL;
  lv_obj_set_pos(row, l->panel_x, y);
  lv_obj_set_size(row, l->panel_w, l->row_h);
  lv_obj_set_clickable(row, true);
  lv_obj_set_user_data(row, (void*)(intptr_t)index);
  lv_obj_add_event_cb(row, on_row, LV_EVENT_CLICKED, app);
  if (focused)
    rect(row, 0, l->row_h / 5, px(app, 2.4f), l->row_h * 3 / 5,
         H2_G99_COLOR_PURPLE_HI, LV_OPA_COVER, px(app, 1.2f));
  return row;
}

static void wifi_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const h2_g99_wifi_snapshot_t* w = &app->wifi_state;
  const int32_t inset = l->panel_inset;
  char line[64];
  text_clipped(info, app->font_small, H2_G99_COLOR_MUTED, l->panel_x + inset, y,
               l->panel_w - 2 * inset, wifi_line(app, line, sizeof(line)));
  y += line_h(app->font_small) + px(app, 6.0f);
  const uint8_t rows = h2_g99_ui_wifi_rows(app);
  const bool editing = app->nav.editing;
  if (w->network_count == 0u) {
    if (w->phase != H2_G99_WIFI_UNAVAILABLE)
      text(info, app->font_body, H2_G99_COLOR_DIM, l->panel_x + inset,
           y + (l->row_h - line_h(app->font_body)) / 2,
           w->phase == H2_G99_WIFI_SCANNING ? "" : "未发现网络");
  }
  uint8_t first = 0u;
  if (editing && app->nav.edit_index >= rows)
    first = (uint8_t)(app->nav.edit_index - rows + 1u);
  for (uint8_t i = 0u; i < rows && first + i < w->network_count; ++i) {
    const uint8_t index = (uint8_t)(first + i);
    const h2_g99_wifi_network_t* n = &w->networks[index];
    const bool focused = editing && app->nav.edit_index == index;
    lv_obj_t* row = add_row(app, info, y + i * l->row_h, index, focused);
    if (row == NULL) continue;
    const bool current =
        w->connected && strcmp(n->ssid, w->connected_ssid) == 0;
    int32_t right = l->panel_w - inset;
    const uint8_t bars = h2_g99_wifi_bars(n->rssi);
    const int32_t bar_w = px(app, 2.2f);
    for (int b = 3; b >= 0; --b) {
      const int32_t bh = px(app, 3.0f + (float)b * 2.4f);
      right -= bar_w;
      rect(row, right, l->row_h / 2 + px(app, 5.0f) - bh, bar_w, bh,
           H2_G99_COLOR_TEXT, b < bars ? LV_OPA_COVER : LV_OPA_20,
           px(app, 0.6f));
      right -= px(app, 1.2f);
    }
    const int32_t tiny = (int32_t)app->tiny_lock.dsc.header.w;
    if (n->security != H2_PAL_WIFI_SECURITY_OPEN) {
      right -= tiny + px(app, 3.0f);
      image(row, &app->tiny_lock, right, (l->row_h - tiny) / 2);
    }
    if (current) {
      right -= tiny + px(app, 3.0f);
      image(row, &app->tiny_check, right, (l->row_h - tiny) / 2);
    }
    const int32_t tx = inset + px(app, 2.0f);
    text_clipped(row, app->font_body,
                 focused ? H2_G99_COLOR_PURPLE_HI
                         : (current ? H2_G99_COLOR_TEXT : H2_G99_COLOR_TEXT),
                 tx, (l->row_h - line_h(app->font_body)) / 2,
                 right - tx - px(app, 4.0f), n->ssid);
  }
  footer(app, info, editing ? "OK 连接 · AI 返回" : "OK 选择网络 · AI 返回");
}

static void slider_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y,
                        uint8_t value, const char* note) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t cw = l->panel_w - 2 * l->panel_inset;
  char number[8];
  (void)snprintf(number, sizeof(number), "%u%%", (unsigned)value);
  text(info, app->font_big,
       app->nav.editing ? H2_G99_COLOR_PURPLE_HI : H2_G99_COLOR_TEXT, x, y,
       number);
  y += line_h(app->font_big) + px(app, 8.0f);
  const int32_t th = px(app, 5.0f);
  lv_obj_t* track = rect(info, x, y - th, cw, th * 3, 0, LV_OPA_TRANSP, 0);
  if (track != NULL) {
    lv_obj_set_clickable(track, true);
    lv_obj_add_event_cb(track, on_slider, LV_EVENT_CLICKED, app);
    rect(track, 0, th, cw, th, 0xFFFFFFu, LV_OPA_20, th / 2);
    const int32_t fill = cw * value / 100;
    rect(track, 0, th, fill, th, H2_G99_COLOR_PURPLE, LV_OPA_COVER, th / 2);
    const int32_t knob = th * 13 / 5;
    rect(track, fill - knob / 2, th + th / 2 - knob / 2, knob, knob, 0xFFFFFFu,
         LV_OPA_COVER, knob / 2);
  }
  y += th * 2 + px(app, 10.0f);
  text_clipped(info, app->font_small, H2_G99_COLOR_MUTED, x, y, cw, note);
  footer(app, info,
         app->nav.editing ? "上下调节 · OK 完成" : "OK 修改 · AI 返回");
}

static void timeout_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t bottom = footer_top(app);
  for (uint8_t i = 0u; i < H2_G99_SCREEN_TIMEOUT_COUNT; ++i) {
    const int32_t ry = y + (int32_t)i * l->row_h;
    if (ry + l->row_h > bottom) break;
    const bool focused = app->nav.editing && app->nav.edit_index == i;
    const bool chosen = app->settings.screen_timeout_index == i;
    lv_obj_t* row = add_row(app, info, ry, i, focused);
    if (row == NULL) continue;
    text(row, app->font_body,
         focused || chosen ? H2_G99_COLOR_PURPLE_HI : H2_G99_COLOR_TEXT,
         l->panel_inset + px(app, 2.0f),
         (l->row_h - line_h(app->font_body)) / 2, kTimeoutNames[i]);
    if (chosen) {
      const int32_t tiny = (int32_t)app->tiny_pick.dsc.header.w;
      image(row, &app->tiny_pick, l->panel_w - l->panel_inset - tiny,
            (l->row_h - tiny) / 2);
    }
  }
  footer(app, info,
         app->nav.editing ? "OK 选择 · AI 返回" : "OK 修改 · AI 返回");
}

static void about_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const h2_g99_config_t* c = app->config;
  char battery[16] = "—";
  if (app->battery_valid)
    (void)snprintf(battery, sizeof(battery), "%u%%",
                   (unsigned)app->battery_percent);
  const char* const rows[6][2] = {
      {"产品", "GizPocket"},
      {"Main", c->main_version != NULL ? c->main_version : "—"},
      {"Loader", c->loader_version != NULL ? c->loader_version : "—"},
      {"板子", c->board_name != NULL ? c->board_name : "—"},
      {"设备 ID", app->device_id[0] != '\0' ? app->device_id : "—"},
      {"电池", battery},
  };
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t key_w = (l->panel_w - 2 * l->panel_inset) * 2 / 5;
  const int32_t step = line_h(app->font_body) + px(app, 4.0f);
  const int32_t bottom = footer_top(app);
  for (int i = 0; i < 6 && y + step <= bottom; ++i, y += step) {
    text(info, app->font_small, H2_G99_COLOR_DIM, x,
         y + (line_h(app->font_body) - line_h(app->font_small)) / 2,
         rows[i][0]);
    text_clipped(info, app->font_body, H2_G99_COLOR_TEXT, x + key_w, y,
                 l->panel_w - 2 * l->panel_inset - key_w, rows[i][1]);
  }
  footer(app, info, "AI 返回");
}

static void settings_info(h2_g99_app_t* app, lv_obj_t* info, uint8_t sel) {
  char label[32];
  (void)snprintf(label, sizeof(label), "设置  %u / %u", (unsigned)sel + 1u,
                 (unsigned)H2_G99_SETTING_COUNT);
  const int32_t y = header(app, info, label, kSettingNames[sel]);
  switch (sel) {
    case H2_G99_SETTING_WIFI:
      wifi_page(app, info, y);
      break;
    case H2_G99_SETTING_VOLUME:
      slider_page(app, info, y, app->settings.volume_percent, "扬声器音量");
      break;
    case H2_G99_SETTING_BRIGHTNESS:
      slider_page(app, info, y, app->settings.brightness_percent,
                  "AMOLED 建议不超过 60%");
      break;
    case H2_G99_SETTING_SCREEN_TIMEOUT:
      timeout_page(app, info, y);
      break;
    case H2_G99_SETTING_ABOUT:
      about_page(app, info, y);
      break;
    default:
      text(info, app->font_body, H2_G99_COLOR_MUTED,
           app->layout.panel_x + app->layout.panel_inset, y + px(app, 4.0f),
           "暂未开放");
      footer(app, info, "AI 返回");
      break;
  }
}

uint8_t h2_g99_ui_wifi_rows(const h2_g99_app_t* app) {
  if (app == NULL || app->font_small == NULL) return 1u;
  const int32_t top = app->layout.panel_y + line_h(app->font_small) +
                      px(app, 6.0f) + line_h(app->font_title) + px(app, 4.0f) +
                      line_h(app->font_small) + px(app, 6.0f);
  const int32_t rows = h2_g99_layout_rows(&app->layout, top, footer_top(app));
  return (uint8_t)(rows > 12 ? 12 : rows);
}

static void build_info(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  lv_obj_clean(layer->info);
  /* Keep page coordinates in screen units, while the parent clips opacity
   * changes and invalidation to the actual info area. */
  lv_obj_t* content = full(layer->info, app);
  if (content == NULL) return;
  lv_obj_set_pos(content, -app->layout.panel_x, -app->layout.panel_y);
  switch (layer->route) {
    case H2_G99_ROUTE_MAIN:
    case H2_G99_ROUTE_BOOT:
      main_info(app, content, layer->sel);
      break;
    case H2_G99_ROUTE_LIBRARY:
      library_info(app, content, layer->sel);
      break;
    case H2_G99_ROUTE_SETTINGS:
      settings_info(app, content, layer->sel);
      break;
    default:
      break;
  }
}

static void show_page(h2_g99_app_t* app, h2_g99_layer_t* layer,
                      h2_g99_route_t route, uint8_t sel) {
  if (route == H2_G99_ROUTE_BOOT) route = H2_G99_ROUTE_MAIN;
  if (!layer->built || layer->route != route || layer->sel != sel ||
      layer->info_rev != app->info_rev) {
    layer->route = route;
    layer->sel = sel;
    layer->info_rev = app->info_rev;
    layer->built = true;
    build_info(app, layer);
  }
  lv_obj_set_hidden(layer->wheel, false);
  lv_obj_set_hidden(layer->info, false);
}

static void hide_layer(h2_g99_layer_t* layer) {
  lv_obj_set_hidden(layer->wheel, true);
  lv_obj_set_hidden(layer->info, true);
}

/* ---------- wheel ---------- */

typedef struct placed {
  float d;
  int item;
  h2_g99_slot_t slot;
} placed_t;

static const h2_g99_image_t* item_image(h2_g99_app_t* app, h2_g99_route_t route,
                                        int item) {
  if (route == H2_G99_ROUTE_LIBRARY) return &app->cover;
  if (route == H2_G99_ROUTE_SETTINGS) return &app->icons[kSettingIcons[item]];
  return &app->icons[kMainIcons[item]];
}

static void apply_slots(h2_g99_app_t* app, h2_g99_layer_t* layer,
                        h2_g99_route_t route, placed_t* list, int count,
                        int32_t dx) {
  /* Draw far slots first so the selection stays on top. */
  for (int i = 1; i < count; ++i) {
    placed_t key = list[i];
    int j = i - 1;
    while (j >= 0 && fabsf(list[j].d) < fabsf(key.d)) {
      list[j + 1] = list[j];
      --j;
    }
    list[j + 1] = key;
  }
  const bool thumbs = route == H2_G99_ROUTE_LIBRARY;
  const int32_t base = thumbs ? app->thumb_px : app->icon_px;
  float best_glow = 0.0f;
  const h2_g99_slot_t* glow_slot = NULL;
  for (int i = 0; i < H2_G99_WHEEL_SLOTS; ++i) {
    lv_obj_t* obj = layer->slots[i];
    if (i >= count || list[i].slot.size < 1.0f ||
        list[i].slot.opacity <= 0.0f) {
      lv_obj_set_hidden(obj, true);
      continue;
    }
    const placed_t* p = &list[i];
    const h2_g99_image_t* img = item_image(app, route, p->item);
    if (layer->slot_src[i] != img) {
      lv_image_set_src(obj, &img->dsc);
      layer->slot_src[i] = img;
    }
    lv_obj_set_hidden(obj, false);
    lv_obj_set_pos(obj, (int32_t)lroundf(p->slot.x) - base / 2 + dx,
                   (int32_t)lroundf(p->slot.y) - base / 2);
    lv_image_set_scale(obj,
                       (uint32_t)lroundf(p->slot.size / (float)base * 256.0f));
    lv_image_set_rotation(obj, (int32_t)lroundf(p->slot.tilt_deg * 10.0f));
    set_image_opa(obj, opa_of(p->slot.opacity));
    if (p->slot.glow > best_glow) {
      best_glow = p->slot.glow;
      glow_slot = &p->slot;
    }
  }
  if (glow_slot == NULL) {
    lv_obj_set_hidden(layer->glow, true);
    return;
  }
  const float diameter = thumbs
                             ? glow_slot->size * 1.35f + 6.0f * app->layout.k
                             : glow_slot->size * 1.24f + 12.0f * app->layout.k;
  lv_obj_set_hidden(layer->glow, false);
  lv_obj_set_pos(layer->glow,
                 (int32_t)lroundf(glow_slot->x) - app->glow_px / 2 + dx,
                 (int32_t)lroundf(glow_slot->y) - app->glow_px / 2);
  lv_image_set_scale(
      layer->glow, (uint32_t)lroundf(diameter / (float)app->glow_px * 256.0f));
  set_image_opa(layer->glow, opa_of((thumbs ? 0.55f : 0.5f) * best_glow));
}

static void place_wheel(h2_g99_app_t* app, h2_g99_layer_t* layer,
                        h2_g99_route_t route, float sel, float dx) {
  if (route == H2_G99_ROUTE_BOOT) route = H2_G99_ROUTE_MAIN;
  const int n = (int)h2_g99_nav_route_count(&app->nav, route);
  placed_t list[H2_G99_WHEEL_SLOTS];
  int count = 0;
  const h2_g99_wheel_kind_t kind =
      route == H2_G99_ROUTE_LIBRARY ? H2_G99_WHEEL_THUMBS : H2_G99_WHEEL_ICONS;
  const int base = (int)lroundf(sel);
  int32_t lo = -3;
  int32_t hi = 3;
  if (n < 5) h2_g99_wheel_span((uint32_t)n, &lo, &hi);
  for (int off = lo; off <= hi && count < H2_G99_WHEEL_SLOTS && n > 0; ++off) {
    const int j = base + off;
    const float d = (float)j - sel;
    if (fabsf(d) >= 2.9f) continue;
    list[count].d = d;
    list[count].item = ((j % n) + n) % n;
    h2_g99_wheel_slot(&app->layout, kind, d, &list[count].slot);
    ++count;
  }
  apply_slots(app, layer, route, list, count, (int32_t)lroundf(dx));
}

static void place_boot_wheel(h2_g99_app_t* app, h2_g99_layer_t* layer,
                             float unfold) {
  placed_t list[5];
  for (int d = -2; d <= 2; ++d) {
    list[d + 2].d = (float)d;
    list[d + 2].item = H2_G99_MAIN_LIBRARY + d;
    h2_g99_boot_slot(&app->layout, d, unfold, &list[d + 2].slot);
  }
  apply_slots(app, layer, H2_G99_ROUTE_MAIN, list, 5, 0);
}

static void set_layer(h2_g99_layer_t* layer, float wheel_opacity,
                      float info_opacity) {
  /* Animate the actual elements. Moving/fading an empty container invalidates
   * its whole column or panel even though only sparse children changed. */
  const lv_opa_t wheel = opa_of(wheel_opacity);
  set_opa(layer->glow, wheel);
  for (size_t i = 0u; i < H2_G99_WHEEL_SLOTS; ++i)
    set_opa(layer->slots[i], wheel);
  lv_obj_t* content = lv_obj_get_child(layer->info, 0);
  if (content != NULL) {
    const lv_opa_t info = opa_of(info_opacity);
    for (uint32_t i = 0u; i < lv_obj_get_child_count(content); ++i)
      set_opa(lv_obj_get_child(content, (int32_t)i), info);
  }
}

/* ---------- frame ---------- */

static void finish_boot(h2_g99_app_t* app) {
  if (app->brand_icon != NULL) {
    lv_obj_delete(app->brand_icon);
    app->brand_icon = NULL;
  }
  if (app->wordmark != NULL) {
    lv_obj_delete(app->wordmark);
    app->wordmark = NULL;
  }
  image_free(app, &app->brand);
  image_free(app, &app->mark);
  set_opa(app->background, LV_OPA_COVER);
}

void h2_g99_ui_frame(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready || app->nav.route == H2_G99_ROUTE_APP)
    return;
  h2_g99_nav_t* nav = &app->nav;
  h2_g99_layer_t* f = &app->layers[app->front];
  h2_g99_layer_t* b = &app->layers[1 - app->front];
  const float p = h2_g99_nav_progress(nav, app->now_ms);
  switch (nav->anim) {
    case H2_G99_TRANSITION_BOOT: {
      h2_g99_boot_frame_t frame;
      h2_g99_boot_frame(h2_g99_nav_elapsed(nav, app->now_ms), &frame);
      set_opa(app->background, opa_of(frame.background_opacity));
      set_opa(app->brand_icon, opa_of(frame.brand_opacity));
      set_opa(app->wordmark, opa_of(frame.brand_opacity));
      show_page(app, f, H2_G99_ROUTE_MAIN, H2_G99_MAIN_LIBRARY);
      place_boot_wheel(app, f, frame.unfold);
      set_layer(f, 1.0f, frame.info_opacity);
      hide_layer(b);
      return;
    }
    case H2_G99_TRANSITION_ENTER:
    case H2_G99_TRANSITION_BACK: {
      h2_g99_page_frame_t frame;
      h2_g99_page_frame(&app->layout, p, &frame);
      show_page(app, f, nav->from_route, nav->from_sel);
      show_page(app, b, nav->to_route, nav->to_sel);
      place_wheel(app, f, nav->from_route, (float)nav->from_sel,
                  frame.old_wheel_dx);
      place_wheel(app, b, nav->to_route, (float)nav->to_sel,
                  frame.new_wheel_dx);
      set_layer(f, frame.old_wheel_opacity, frame.old_info_opacity);
      set_layer(b, frame.new_wheel_opacity, frame.new_info_opacity);
      app->swap_pending = true;
      return;
    }
    case H2_G99_TRANSITION_ROTATE: {
      /* Ease from the released position to its detent. Project the target
       * information once; an opacity fade would repaint it every frame. */
      const float sel =
          (float)nav->from_sel + nav->rotate_from +
          ((float)nav->rotate_dir - nav->rotate_from) * h2_g99_ease_snap(p);
      show_page(app, f, nav->route, nav->to_sel);
      place_wheel(app, f, nav->route, sel, 0.0f);
      set_layer(f, 1.0f, 1.0f);
      hide_layer(b);
      return;
    }
    default:
      break;
  }
  if (app->brand_icon != NULL || app->wordmark != NULL) finish_boot(app);
  if (app->swap_pending) {
    app->swap_pending = false;
    app->front = (uint8_t)(1 - app->front);
    f = &app->layers[app->front];
    b = &app->layers[1 - app->front];
  }
  const uint8_t sel =
      nav->route == H2_G99_ROUTE_MAIN ? nav->main_sel : nav->sub_sel;
  /* A finger moves only the wheel until a detent is committed. */
  const bool dragged = app->dragging && wheel_turnable(app);
  const float position = (float)sel + (dragged ? app->drag_offset : 0.0f);
  /* Keep the committed selection while held. Rebuild its information
   * once at snap, rather than repeatedly at a noisy half-slot crossing. */
  show_page(app, f, nav->route, sel);
  place_wheel(app, f, nav->route, position, 0.0f);
  set_layer(f, 1.0f, 1.0f);
  hide_layer(b);
}

void h2_g99_ui_pump(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  const uint64_t delta = app->now_ms - app->last_tick_ms;
  app->last_tick_ms = app->now_ms;
  lv_tick_inc((uint32_t)(delta > 1000u ? 1000u : delta));
  (void)lv_timer_handler();
}

/* ---------- screen, suspend, keyboard ---------- */

void h2_g99_ui_set_screen(h2_g99_app_t* app, bool on) {
  if (app == NULL || !app->lvgl_ready) return;
  const h2_pal_display_t* display = app->runtime->display;
  if (on) {
    (void)h2_pal_display_set_brightness_percent(
        display, app->settings.brightness_percent);
    if (app->nav.route == H2_G99_ROUTE_APP) return;
    lv_obj_set_hidden(app->blackout, true);
    app->suppress_flush = false;
    lv_obj_invalidate(app->screen);
    return;
  }
  if (app->nav.route != H2_G99_ROUTE_APP) {
    lv_obj_set_hidden(app->blackout, false);
    lv_refr_now(app->display);
    app->suppress_flush = true;
  }
  (void)h2_pal_display_set_brightness_percent(display, 0u);
}

void h2_g99_ui_suspend(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  lv_refr_now(app->display);
  app->suppress_flush = true;
  lv_timer_pause(lv_display_get_refr_timer(app->display));
}

void h2_g99_ui_resume(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  app->suppress_flush = !app->nav.screen_on;
  lv_timer_resume(lv_display_get_refr_timer(app->display));
  app->info_rev++;
  lv_obj_invalidate(app->screen);
}

void h2_g99_ui_open_keyboard(h2_g99_app_t* app, const char* ssid) {
  if (app == NULL || !app->lvgl_ready || app->keyboard_panel != NULL) return;
  const h2_g99_layout_t* l = &app->layout;
  (void)snprintf(app->keyboard_ssid, sizeof(app->keyboard_ssid), "%s",
                 ssid != NULL ? ssid : "");
  lv_obj_t* panel = full(app->screen, app);
  if (panel == NULL) return;
  lv_obj_move_to_index(panel, (int32_t)lv_obj_get_index(app->blackout));
  lv_obj_set_style_bg_color(panel, lv_color_hex(0x0B0620u), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(panel, LV_OPA_90, LV_PART_MAIN);
  lv_obj_set_clickable(panel, true);
  char title[64];
  (void)snprintf(title, sizeof(title), "连接 %s", app->keyboard_ssid);
  const int32_t x = l->pad * 2;
  text_clipped(panel, app->font_body, H2_G99_COLOR_TEXT, x, l->pad,
               l->width - 4 * l->pad, title);
  lv_obj_t* area = lv_textarea_create(panel);
  lv_obj_t* keyboard = lv_keyboard_create(panel);
  if (area == NULL || keyboard == NULL) {
    lv_obj_delete(panel);
    return;
  }
  const int32_t field_y = l->pad + line_h(app->font_body) + px(app, 6.0f);
  lv_obj_set_pos(area, x, field_y);
  lv_obj_set_size(area, l->width - 4 * l->pad,
                  line_h(app->font_body) + px(app, 12.0f));
  lv_textarea_set_one_line(area, true);
  lv_textarea_set_password_mode(area, true);
  lv_textarea_set_max_length(area, H2_PAL_WIFI_PASSWORD_MAX);
  lv_textarea_set_placeholder_text(area, "密码");
  lv_obj_set_style_text_font(area, app->font_body, LV_PART_MAIN);
  lv_obj_set_style_text_font(area, app->font_body,
                             LV_PART_TEXTAREA_PLACEHOLDER);
  const int32_t keyboard_y = field_y + line_h(app->font_body) + px(app, 20.0f);
  lv_obj_set_pos(keyboard, 0, keyboard_y);
  lv_obj_set_size(keyboard, l->width, l->height - keyboard_y);
  lv_keyboard_set_textarea(keyboard, area);
  lv_obj_add_event_cb(keyboard, on_keyboard, LV_EVENT_READY, app);
  lv_obj_add_event_cb(keyboard, on_keyboard, LV_EVENT_CANCEL, app);
  app->keyboard_panel = panel;
  app->keyboard_text = area;
  app->keyboard = keyboard;
}

void h2_g99_ui_set_keyboard_text(h2_g99_app_t* app, const char* text) {
  if (app == NULL || app->keyboard_text == NULL || text == NULL) return;
  lv_textarea_set_text(app->keyboard_text, text);
}

void h2_g99_ui_close_keyboard(h2_g99_app_t* app, char* buffer,
                              size_t capacity) {
  if (buffer != NULL && capacity > 0u) buffer[0] = '\0';
  if (app == NULL || app->keyboard_panel == NULL) return;
  if (buffer != NULL && capacity > 0u)
    (void)snprintf(buffer, capacity, "%s",
                   lv_textarea_get_text(app->keyboard_text));
  lv_obj_delete(app->keyboard_panel);
  app->keyboard_panel = NULL;
  app->keyboard_text = NULL;
  app->keyboard = NULL;
}

/* ---------- init / deinit ---------- */

static bool create_layer(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  layer->wheel = full(app->screen, app);
  if (layer->wheel == NULL) return false;
  const int32_t wheel_right =
      app->layout.sel_x + (app->glow_px + 1) / 2 + px(app, 2.0f);
  lv_obj_set_width(layer->wheel, wheel_right < app->layout.width
                                     ? wheel_right
                                     : app->layout.width);
  layer->glow = image(layer->wheel, &app->glow, 0, 0);
  if (layer->glow == NULL) return false;
  lv_obj_set_style_image_recolor(layer->glow, lv_color_hex(H2_G99_COLOR_PURPLE),
                                 LV_PART_MAIN);
  for (int i = 0; i < H2_G99_WHEEL_SLOTS; ++i) {
    layer->slots[i] = image(layer->wheel, &app->icons[0], 0, 0);
    layer->slot_src[i] = &app->icons[0];
    if (layer->slots[i] == NULL) return false;
    lv_obj_set_style_image_recolor(layer->slots[i], lv_color_hex(0xFFFFFFu),
                                   LV_PART_MAIN);
    /* A8 uses the colour directly. Transparent recolour opacity preserves
     * the multicolour Orbit cover when the same slot changes source. */
    lv_obj_set_style_image_recolor_opa(layer->slots[i], LV_OPA_TRANSP,
                                       LV_PART_MAIN);
    lv_obj_set_hidden(layer->slots[i], true);
  }
  layer->info = plain(app->screen);
  if (layer->glow == NULL || layer->info == NULL) return false;
  lv_obj_set_pos(layer->info, app->layout.panel_x, app->layout.panel_y);
  lv_obj_set_size(layer->info, app->layout.panel_w, app->layout.panel_h);
  hide_layer(layer);
  return true;
}

static lv_font_t* make_font(int32_t size) {
  lv_font_t* font = lv_tiny_ttf_create_data_ex(
      h2_g99_font_data, h2_g99_font_size, size, LV_FONT_KERNING_NONE, 128u);
  /* Keyboard and textarea symbols live in the built-in symbol font. */
  if (font != NULL) font->fallback = LV_FONT_DEFAULT;
  return font;
}

/* Populate TinyTTF's real bitmap cache before interactive animation.
 * Layout-only glyph metrics do not rasterize these glyphs. */
static bool warm_text(lv_font_t* font, const char* value) {
  /* Only built-in UTF-8 literals reach this initializer. */
  const uint8_t* text = (const uint8_t*)value;
  while (*text != 0u) {
    uint32_t codepoint = *text++;
    if (codepoint >= 0x80u) {
      const unsigned extra = codepoint < 0xe0u   ? 1u
                             : codepoint < 0xf0u ? 2u
                                                 : 3u;
      codepoint &= 0x7fu >> (extra + 1u);
      for (unsigned i = 0u; i < extra; ++i) {
        if ((*text & 0xc0u) != 0x80u) return false;
        codepoint = (codepoint << 6u) | (*text++ & 0x3fu);
      }
    }
    lv_font_glyph_dsc_t glyph;
    memset(&glyph, 0, sizeof(glyph));
    if (!lv_font_get_glyph_dsc(font, &glyph, codepoint, 0u)) return false;
    if (glyph.resolved_font != font || glyph.box_w == 0u || glyph.box_h == 0u)
      continue;
    const void* bitmap = lv_font_get_glyph_bitmap(&glyph, NULL);
    lv_font_glyph_release_draw_data(&glyph);
    if (bitmap == NULL) return false;
  }
  return true;
}

static bool warm_fonts(h2_g99_app_t* app) {
  for (size_t i = 0u; i < H2_G99_MAIN_COUNT; ++i)
    if (!warm_text(app->font_hero, kMainNames[i])) return false;
  for (size_t i = 0u; i < H2_G99_SETTING_COUNT; ++i)
    if (!warm_text(app->font_title, kSettingNames[i])) return false;
  return warm_text(app->font_title, kAppName) &&
         warm_text(app->font_small, kAppAuthor) &&
         warm_text(app->font_small, kAppDescription) &&
         warm_text(app->font_small,
                   "0123456789:/ · 资料库 设置 来源 绘图 输入 OK 开始 AI 返回 "
                   "未连接 未发现网络") &&
         warm_text(app->font_body,
                   "0123456789%Wi-Fi · 已安装 个应用 即将推出 已连接 电量 "
                   "开始游戏 内置 几何 按键") &&
         warm_text(app->font_big, "0123456789%");
}

static bool render_art(h2_g99_app_t* app) {
  const h2_g99_layout_t* l = &app->layout;
  app->icon_px = px(app, 34.0f);
  app->thumb_px = px(app, 50.0f);
  app->glow_px = (int32_t)lroundf((float)app->thumb_px * 1.35f + 6.0f * l->k);
  for (int i = 0; i < H2_G99_ICON_COUNT; ++i) {
    if (!argb_alloc(app, &app->icons[i], app->icon_px, app->icon_px) ||
        !h2_g99_art_icon((h2_g99_icon_t)i, 0xFFFFFFu, app->icons[i].pixels,
                         app->icon_px))
      return false;
    image_to_alpha(app, &app->icons[i]);
  }
  const int32_t tiny = (int32_t)lroundf((float)l->font_small * 1.1f);
  if (!argb_alloc(app, &app->tiny_wifi, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_WIFI, H2_G99_COLOR_MUTED,
                       app->tiny_wifi.pixels, tiny) ||
      !argb_alloc(app, &app->tiny_lock, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_LOCK, H2_G99_COLOR_MUTED,
                       app->tiny_lock.pixels, tiny) ||
      !argb_alloc(app, &app->tiny_check, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_CHECK, H2_G99_COLOR_OK,
                       app->tiny_check.pixels, tiny) ||
      !argb_alloc(app, &app->tiny_pick, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_CHECK, H2_G99_COLOR_PURPLE_HI,
                       app->tiny_pick.pixels, tiny))
    return false;
  if (!argb_alloc(app, &app->cover, app->thumb_px, app->thumb_px) ||
      !h2_g99_art_cover(app->cover.pixels, app->thumb_px) ||
      !argb_alloc(app, &app->glow, app->glow_px, app->glow_px) ||
      !h2_g99_art_glow(app->glow.pixels, app->glow_px))
    return false;
  image_to_alpha(app, &app->glow);
  const h2_g99_brand_layout_t* brand = &l->brand;
  if (!argb_alloc(app, &app->brand, brand->icon_image_w, brand->icon_image_h) ||
      !h2_g99_art_brand_icon(app->brand.pixels, brand->icon_image_w,
                             brand->icon_image_h) ||
      !argb_alloc(app, &app->mark, brand->wordmark_image_w,
                  brand->wordmark_image_h) ||
      !h2_g99_art_wordmark(app->mark.pixels, brand->cell, brand->shadow))
    return false;
  app->bg_spec = (h2_g99_background_t){l->width, l->height,
                                       l->panel_x - px(app, 24.0f), l->k};
  if (!image_alloc(app, &app->bg, l->width, l->height, LV_COLOR_FORMAT_RGB565,
                   2u))
    return false;
  /* The background is a static picture, drawn once. */
  return h2_g99_background_render(&app->bg_spec, 0u, (uint16_t*)app->bg.pixels,
                                  l->width, 0, l->height);
}

static void free_art(h2_g99_app_t* app) {
  for (int i = 0; i < H2_G99_ICON_COUNT; ++i) image_free(app, &app->icons[i]);
  image_free(app, &app->tiny_wifi);
  image_free(app, &app->tiny_lock);
  image_free(app, &app->tiny_check);
  image_free(app, &app->tiny_pick);
  image_free(app, &app->cover);
  image_free(app, &app->glow);
  image_free(app, &app->brand);
  image_free(app, &app->mark);
  image_free(app, &app->bg);
}

static const h2_pal_mem_api_t* render_mem(const h2_g99_app_t* app) {
  return app->config->render_mem != NULL ? app->config->render_mem
                                         : app->runtime->mem;
}

h2_pal_result_t h2_g99_ui_init(h2_g99_app_t* app) {
  if (app == NULL || app->lvgl_ready) return H2_PAL_ERR_INVALID_STATE;
  const h2_g99_layout_t* l = &app->layout;
  if (!render_art(app)) {
    free_art(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  /* Bound the fast allocation to one small buffer. All persistent LVGL
   * objects and glyph caches use Runtime memory, not this scarce heap. */
  const int32_t rows = l->height < 16 ? l->height : 16;
  app->render_bytes = (size_t)l->width * (size_t)rows * 2u;
  app->render_buffer = h2_pal_mem_alloc(render_mem(app), app->render_bytes);
  if (app->render_buffer == NULL && rows > 8) {
    app->render_bytes = (size_t)l->width * 8u * 2u;
    app->render_buffer = h2_pal_mem_alloc(render_mem(app), app->render_bytes);
  }
  if (app->render_buffer == NULL) {
    free_art(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  const h2_lvgl_platform_config_t platform = {
      .allocator = app->runtime->mem,
      .task_api = app->runtime->task,
      .sync_api = app->runtime->sync,
      .queue_api = app->runtime->queue,
      .time_api = app->runtime->time,
  };
  if (h2_lvgl_platform_init(&platform) != 0) {
    h2_pal_mem_free(render_mem(app), app->render_buffer);
    app->render_buffer = NULL;
    free_art(app);
    return H2_PAL_ERR_UNAVAILABLE;
  }
  lv_init();
  app->lvgl_ready = true;
  app->last_tick_ms = app->now_ms;
  app->font_hero = make_font(l->font_hero);
  app->font_title = make_font(l->font_title);
  app->font_body = make_font(l->font_body);
  app->font_small = make_font(l->font_small);
  app->font_big = make_font((int32_t)lroundf((float)l->font_title * 1.7f));
  app->display = lv_display_create(l->width, l->height);
  if (app->font_hero == NULL || app->font_title == NULL ||
      app->font_body == NULL || app->font_small == NULL ||
      app->font_big == NULL || app->display == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  if (!warm_fonts(app)) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_display_set_user_data(app->display, app);
  lv_timer_set_period(lv_display_get_refr_timer(app->display), 16u);
  lv_display_set_color_format(app->display, LV_COLOR_FORMAT_RGB565);
  lv_display_set_flush_cb(app->display, display_flush);
  lv_display_set_buffers(app->display, app->render_buffer, NULL,
                         (uint32_t)app->render_bytes,
                         LV_DISPLAY_RENDER_MODE_PARTIAL);
  app->screen = lv_screen_active();
  lv_obj_set_scrollable(app->screen, false);
  lv_obj_set_style_bg_color(app->screen, lv_color_hex(0x000000u), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(app->screen, LV_OPA_COVER, LV_PART_MAIN);
  app->background = image(app->screen, &app->bg, 0, 0);
  app->catcher = full(app->screen, app);
  if (app->background == NULL || app->catcher == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_obj_set_style_opa(app->background, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_clickable(app->catcher, true);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESSED, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESSING, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_RELEASED, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESS_LOST, app);
  if (!create_layer(app, &app->layers[0]) ||
      !create_layer(app, &app->layers[1])) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  app->brand_icon =
      image(app->screen, &app->brand, l->brand.icon_x, l->brand.group_y);
  app->wordmark =
      image(app->screen, &app->mark, l->brand.wordmark_x, l->brand.wordmark_y);
  app->blackout =
      rect(app->screen, 0, 0, l->width, l->height, 0x000000u, LV_OPA_COVER, 0);
  if (app->brand_icon == NULL || app->wordmark == NULL ||
      app->blackout == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_obj_set_hidden(app->blackout, true);
  const h2_pal_touch_api_t* source =
      app->config->touch != NULL ? app->config->touch : app->runtime->touch;
  if (source != NULL) {
    /* LVGL reads touch through the filter: one press per contact. */
    h2_g99_touch_filter_init(&app->touch_filter, source, app->runtime->time);
    const h2_lvgl_touch_config_t touch = {
        h2_g99_touch_filter_api(&app->touch_filter), app->runtime->mem,
        app->display};
    if (h2_lvgl_touch_create(&touch, &app->touch) != H2_PAL_OK) {
      app->touch = NULL;
    } else {
      for (lv_indev_t* indev = lv_indev_get_next(NULL); indev != NULL;
           indev = lv_indev_get_next(indev)) {
        /* Sample at the filter's cadence instead of the display's refresh
         * period, which can leave a quick gesture unread between frames. */
        lv_timer_t* timer = lv_indev_get_read_timer(indev);
        if (timer != NULL) lv_timer_set_period(timer, H2_G99_TOUCH_READ_MS);
        lv_indev_add_event_cb(indev, on_indev_press, LV_EVENT_PRESSED, app);
      }
    }
  }
  app->touch_request = (h2_g99_touch_request_t){-1, -1, -1, H2_G99_TEXT_NONE};
  return H2_PAL_OK;
}

void h2_g99_ui_deinit(h2_g99_app_t* app) {
  if (app == NULL) return;
  if (app->lvgl_ready) {
    if (app->touch != NULL) h2_lvgl_touch_destroy(app->touch);
    app->touch = NULL;
    app->keyboard_panel = NULL;
    lv_font_t** fonts[] = {&app->font_hero, &app->font_title, &app->font_body,
                           &app->font_small, &app->font_big};
    if (app->display != NULL) lv_display_delete(app->display);
    app->display = NULL;
    for (size_t i = 0; i < sizeof(fonts) / sizeof(fonts[0]); ++i) {
      if (*fonts[i] != NULL) lv_tiny_ttf_destroy(*fonts[i]);
      *fonts[i] = NULL;
    }
    lv_deinit();
    h2_lvgl_platform_deinit();
    app->lvgl_ready = false;
  }
  if (app->render_buffer != NULL)
    h2_pal_mem_free(render_mem(app), app->render_buffer);
  app->render_buffer = NULL;
  free_art(app);
}
